svg.script:
(() => {
 const root=document.documentElement, layers=[...root.querySelectorAll('.depth')], reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let x=0,y=0,tx=0,ty=0,raf=0,enabled=true,paused=false,strength=1;
 const blocked=()=>reduced.matches && root.dataset.motion!=='enabled';
 function reset(){if(raf)cancelAnimationFrame(raf);raf=0;x=y=tx=ty=0;layers.forEach(l=>{l.style.removeProperty('--dx');l.style.removeProperty('--dy');});}
 function frame(){raf=0;if(paused||!enabled||blocked())return;x+=(tx-x)*.09;y+=(ty-y)*.09;layers.forEach(l=>{const d=Number(l.dataset.depth);l.style.setProperty('--dx',`${(x*d).toFixed(3)}px`);l.style.setProperty('--dy',`${(y*d).toFixed(3)}px`);});if(Math.abs(tx-x)+Math.abs(ty-y)>.02)raf=requestAnimationFrame(frame);}
 function schedule(){if(!raf&&!paused&&enabled&&!blocked())raf=requestAnimationFrame(frame);}
 root.addEventListener('pointermove',e=>{if(paused||!enabled||blocked())return;const r=root.getBoundingClientRect();tx=((e.clientX-r.left)/r.width-.5)*32*strength;ty=((e.clientY-r.top)/r.height-.5)*18*strength;schedule();});
 root.addEventListener('pointerleave',()=>{tx=ty=0;schedule();});
 reduced.addEventListener('change',()=>{delete root.dataset.motion;reset();});
 window.sceneControls={
  pause(value){paused=Boolean(value);root.dataset.paused=String(paused);if(paused){if(raf)cancelAnimationFrame(raf);raf=0;}else{root.dataset.motion='enabled';schedule();}},
  parallax(value){enabled=Boolean(value);reset();},
  strength(value){strength=Math.max(0,Math.min(2,Number(value)||0));reset();},
  layer(id,visible){const layer=layers.find(l=>l.id===id);if(layer)layer.style.display=visible?'':'none';},
  layers:layers.map(l=>({id:l.id,label:l.dataset.label,depth:Number(l.dataset.depth)}))
 };
})();
